SELECT count(*) cnt, ifnull(min(tracking_process_id), 0) min, ifnull(max(tracking_process_id), 0) max FROM ttracking_process_info A WHERE NOT EXISTS( SELECT tracking_process_id, request_tracking_id FROM tracking_task_processing_info B WHERE B.tracking_process_id = A.tracking_process_id AND B.request_tracking_id = A.request_tracking_id )
AND tracking_status = #{sequenceStatus}
and tracking_process_type in
#{item}

SELECT tracking_process_id, request_tracking_id, tracking_process_type, digital_twin_id, digital_object_id, tracking_command, tracking_process_identifier, event_condition, event_occurred, event_delay, event_end_date, tracking_kafka_group, tracking_kafka_topic, tracking_status_change_time, data_filter_type, federated_twin_id, federated_digital_object_id, tracking_status FROM tracking_process_info A WHERE 1=1
AND NOT EXISTS( SELECT tracking_process_id, request_tracking_id FROM tracking_task_processing_info B WHERE B.tracking_process_id = A.tracking_process_id AND B.request_tracking_id = A.request_tracking_id)
AND tracking_process_id = #{trackingProcessId}
and tracking_process_id in
#{item}
AND tracking_status = #{trackingStatus}
ORDER BY A.tracking_process_id
LIMIT #{start},#{end}

